# Public API (cm:*)
  @api cm:setContext(newTake)  @ 426-431
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 424
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 425
  @api cm:clearTake()  @ 433-438
  @api cm:boundTake()  @ 441
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 440
  @api cm:boundTrack()  @ 444
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 443
  @api cm:setTrack(newTrack)  @ 446-451
  @api cm:pollUndo()  @ 454
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 453
  @api cm:isDeclared(key)  @ 491
      @contract  non-raising existence test against the schema; true iff key is declared  @ 490
  @api cm:get(key, opts)  @ 498-505
      -- pick is orthogonal to the merge mode: it indexes whatever that mode resolved, so only the
      -- one entry crosses the boundary. A nil pick is indistinguishable from none (see the spec).
  @api cm:getAt(level, key)  @ 508-517
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 507
  @api cm:valueFor(handle, scope, key)  @ 520-527
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 519
  @api cm:defaultFor(key)  @ 530-533
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 529
  -- Writing
  @api cm:set(level, key, value)  @ 538-548
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 537
  @api cm:remove(level, key)  @ 551-562
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 550
  @api cm:assign(level, updates)  @ 565-579
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 564

